#!/usr/bin/env python3
"""Render a project's docs into one architecture page (references/contract.md, "Generated files").

Writes docs/generated/architecture.md and docs/generated/index.html: the project layer first
(overview, spec, process, other docs, decisions), then the component layer (a dependency graph, then
each component page, dependencies first). Output is a pure function of the docs: no clock, no
absolute path, no locale, so --check can compare bytes.

    render_docs.py [project]                       write the generated files
    render_docs.py [project] --check               exit 1 if they drifted; run the update trigger
    render_docs.py [project] --pr-summary          markdown block for a PR description
    render_docs.py [project] --trigger-audit RANGE list trigger hits over merged commits

Standard library only. It loads components.py and validate_docs.py from beside itself. Rendering reads
no manifest; the update trigger resolves components with components.py, so it needs `tomllib`
(Python 3.11+) for a TOML manifest.
Exit 0 ok, 1 drift or trigger failure, 2 unreadable input or unresolvable base, 3 needs-input.
"""

from __future__ import annotations

import argparse
import fnmatch
import heapq
import html
import json
import os
import re
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable
from urllib.parse import quote

import components
from validate_docs import FENCE_RE, split_frontmatter

TOOL = "render_docs.py"
MIN_PYTHON = (3, 9)
MERMAID_VERSION = "11.4.1"
MERMAID_SRI = "sha384-rbtjAdnIQE/aQJGEgXrVUlMibdfTSa4PQju4HDhN3sR2PmaKFzhEafuePsl9H/9I"
MERMAID_URL = f"https://cdn.jsdelivr.net/npm/mermaid@{MERMAID_VERSION}/dist/mermaid.min.js"
GENERATED_MD = "docs/generated/architecture.md"
GENERATED_HTML = "docs/generated/index.html"
HEADER = "<!-- generated by render_docs.py; do not edit -->"
LEAD_DOCS = ("overview.md", "spec.md", "process.md")
PARAGRAPH_MAX = 400
PR_SUMMARY_LIMIT = 60_000
TRIGGER_MODES = ("warn", "fail")
NO_BASE = "warning: trigger-skipped: no diff base"


class InputError(Exception):
    """Unreadable or invalid input; the message names the file or ref. Exit 2."""


# --- reading docs ----------------------------------------------------------------------------------


@dataclass
class Diagram:
    heading: str | None
    anchor: str | None
    para: str
    body: str


@dataclass
class Doc:
    rel: str  # POSIX path from the project root
    title: str
    fm: dict
    diagrams: list[Diagram]
    paras: dict[str, str]  # heading text -> its first paragraph, first occurrence only


@dataclass
class _Section:
    heading: str | None
    anchor: str | None
    lines: list[str] = field(default_factory=list)
    bodies: list[str] = field(default_factory=list)


HEADING_RE = re.compile(r"^ {0,3}(#{1,6})[ \t]+(.*?)(?:[ \t]+#+)?[ \t]*$")
SKIPPED_BLOCK_RE = re.compile(r"^\s*(\||[-*+]\s|\d+[.)]\s|>|<!--)")


def _slug(text: str) -> str:
    return re.sub(r"[^\w\- ]", "", text.lower()).replace(" ", "-")


def _first_paragraph(lines: list[str]) -> str:
    para: list[str] = []
    skip = False
    for line in lines + [""]:
        if not line.strip():
            if para:
                break
            skip = False
        elif skip or (not para and SKIPPED_BLOCK_RE.match(line)):
            skip = True
        else:
            para.append(line.strip())
    return " ".join(para)


def _clip(text: str, limit: int = PARAGRAPH_MAX) -> str:
    return text if len(text) <= limit else text[: limit - 3].rstrip() + "..."


def parse_doc(rel: str, text: str) -> Doc:
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")
    fm, _ = split_frontmatter(text)
    start = 0
    if fm is not None:
        start = next(i + 1 for i in range(1, len(lines)) if lines[i].strip() == "---")
    sections = [_Section(None, None)]
    seen: dict[str, int] = {}
    title = None
    fence: tuple[str, int, bool, int] | None = None  # char, length, is mermaid, opening line number
    body: list[str] = []
    for n in range(start, len(lines)):
        line = lines[n]
        m = FENCE_RE.match(line)
        if fence is None:
            if m and not (m.group(1)[0] == "`" and "`" in m.group(2)):
                is_mermaid = re.match(r"mermaid\b", m.group(2).strip()) is not None
                fence, body = (m.group(1)[0], len(m.group(1)), is_mermaid, n + 1), []
                sections[-1].lines.append("")
                continue
            h = HEADING_RE.match(line)
            if h:
                slug = _slug(h.group(2))
                count = seen.get(slug, 0)
                seen[slug] = count + 1
                if title is None and len(h.group(1)) == 1:
                    title = h.group(2)
                sections.append(_Section(h.group(2), slug if count == 0 else f"{slug}-{count}"))
            else:
                sections[-1].lines.append(line)
        elif m and m.group(1)[0] == fence[0] and len(m.group(1)) >= fence[1] and not m.group(2).strip():
            if fence[2] and any(b.strip() for b in body):
                sections[-1].bodies.append("\n".join(body))
            fence = None
        else:
            body.append(line)
    if fence is not None:
        raise InputError(f"{rel}:{fence[3]}: unterminated {fence[0] * fence[1]} fence")
    fm = fm or {}
    fm_title = fm.get("title")
    title = fm_title if isinstance(fm_title, str) and fm_title.strip() else (title or rel)
    paras: dict[str, str] = {}
    diagrams: list[Diagram] = []
    for sec in sections:
        para = _first_paragraph(sec.lines)
        if sec.heading is not None:
            paras.setdefault(sec.heading, para)
        diagrams += [Diagram(sec.heading, sec.anchor, para, b) for b in sec.bodies]
    return Doc(rel, title, fm, diagrams, paras)


def _read_doc(project: Path, rel: str) -> Doc:
    try:
        text = (project / rel).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise InputError(f"{rel}: unreadable ({type(exc).__name__})") from exc
    return parse_doc(rel, text)


def _discover(project: Path) -> tuple[list[str], list[str]]:
    """(project-layer docs in contract order, component pages by path), as POSIX relpaths."""
    docs = project / "docs"
    if not docs.is_dir():
        raise InputError(f"{project}: no docs/ directory")
    found: list[str] = []
    for root, dirs, files in os.walk(docs):
        dirs[:] = sorted(d for d in dirs if not d.startswith("."))
        base = Path(root).relative_to(project).as_posix()
        found += [f"{base}/{f}" for f in files if f.endswith(".md")]
    found.sort()

    def top(rel: str) -> str:
        parts = rel.split("/")
        return parts[1] if len(parts) > 2 else ""

    lead = [f"docs/{n}" for n in LEAD_DOCS if f"docs/{n}" in found]
    other = [r for r in found if top(r) not in ("components", "generated", "decisions") and r not in lead]
    decisions = [r for r in found if top(r) == "decisions"]
    pages = [r for r in found if top(r) == "components"]
    return lead + other + decisions, pages


# --- model -----------------------------------------------------------------------------------------


@dataclass
class Page:
    doc: Doc
    name: str
    deps: list[str]


def _load_pages(project: Path, rels: list[str]) -> list[Page]:
    pages: dict[str, Page] = {}
    for rel in rels:
        doc = _read_doc(project, rel)
        name, deps = doc.fm.get("component"), doc.fm.get("depends-on")
        if not isinstance(name, str) or not name.strip():
            raise InputError(f"{rel}: bad frontmatter: missing or empty 'component'")
        if not isinstance(deps, list):
            raise InputError(f"{rel}: bad frontmatter: 'depends-on' must be a list such as [a, b]")
        if name in pages:
            raise InputError(f"{rel}: duplicate component {name!r}, also {pages[name].doc.rel}")
        pages[name] = Page(doc, name, sorted({str(d) for d in deps}))
    return list(pages.values())


def _order(pages: list[Page]) -> list[Page]:
    """Dependencies first, ties by codepoint of the name. A cycle raises InputError naming it."""
    by_name = {p.name: p for p in pages}
    deps = {p.name: [d for d in p.deps if d in by_name and d != p.name] for p in pages}
    waiting = {n: len(d) for n, d in deps.items()}
    users: dict[str, list[str]] = {n: [] for n in by_name}
    for n, ds in deps.items():
        for d in ds:
            users[d].append(n)
    ready = [n for n, c in waiting.items() if c == 0]
    heapq.heapify(ready)
    ordered: list[str] = []
    while ready:
        n = heapq.heappop(ready)
        ordered.append(n)
        for u in users[n]:
            waiting[u] -= 1
            if waiting[u] == 0:
                heapq.heappush(ready, u)
    left = {n for n, c in waiting.items() if c > 0}
    if left:
        path = [min(left)]
        while True:
            nxt = min(d for d in deps[path[-1]] if d in left)
            if nxt in path:
                cycle = path[path.index(nxt):] + [nxt]
                raise InputError("depends-on cycle: " + " -> ".join(cycle)
                                 + " (the manifest decides; fix the page's depends-on)")
            path.append(nxt)
    return [by_name[n] for n in ordered]


def _label(text: str) -> str:
    for ch, code in (("&", "#amp;"), ('"', "#quot;"), ("<", "#lt;"), (">", "#gt;")):
        text = text.replace(ch, code)
    return text


def _graph(ordered: list[Page]) -> str:
    ids = {p.name: f"n{i}" for i, p in enumerate(ordered)}
    lines = ["flowchart LR"] + [f'  {ids[p.name]}["{_label(p.name)}"]' for p in ordered]
    lines += [f"  {ids[p.name]} --> {ids[d]}" for p in ordered for d in p.deps if d in ids and d != p.name]
    return "\n".join(lines)


@dataclass
class Shown:
    heading: str | None
    para: str
    body: str
    href: str | None  # link to the heading in the source
    label: str | None


@dataclass
class Entry:
    heading: str
    href: str | None  # link to the source file
    label: str | None
    para: str
    used_by: str | None
    diagrams: list[Shown]


def _href(rel: str, anchor: str | None = None) -> str:
    target = quote(rel[len("docs/"):], safe="/")
    return "../" + target + (f"#{quote(anchor)}" if anchor else "")


def _entry(doc: Doc, heading: str, para: str = "", used_by: str | None = None) -> Entry:
    shown = [Shown(d.heading or doc.title, _clip(d.para), d.body, _href(doc.rel, d.anchor),
                   f"{doc.rel}#{d.anchor}" if d.anchor else doc.rel) for d in doc.diagrams]
    return Entry(heading, _href(doc.rel), doc.rel, para, used_by, shown)


def build(project: Path) -> list[tuple[str, list[Entry]]]:
    """The layers, in output order, as (label, entries)."""
    project_rels, page_rels = _discover(project)
    docs = [_read_doc(project, r) for r in project_rels]
    layers = [("Project", [_entry(d, d.title) for d in docs])]
    pages = _load_pages(project, page_rels)
    if pages:
        ordered = _order(pages)
        users: dict[str, list[str]] = {p.name: [] for p in ordered}
        for p in ordered:
            users_of = [d for d in p.deps if d in users and d != p.name]
            for d in users_of:
                users[d].append(p.name)
        graph = Entry("Dependency graph", None, None, "", None, [Shown(None, "", _graph(ordered), None, None)])
        entries = [graph] + [
            _entry(p.doc, p.name, p.doc.paras.get("Purpose", ""), ", ".join(sorted(users[p.name])) or "none")
            for p in ordered]
        layers.append(("Components", entries))
    return layers


# --- serializers -----------------------------------------------------------------------------------


def fence_for(body: str) -> str:
    longest = max((len(run) for run in re.findall(r"`+", body)), default=0)
    return "`" * max(3, longest + 1)


def _mermaid_block(body: str) -> str:
    f = fence_for(body)
    return f"{f}mermaid\n{body}\n{f}\n"


def to_markdown(layers: list[tuple[str, list[Entry]]]) -> str:
    out = [HEADER, "", "# Architecture", ""]
    for label, entries in layers:
        out += [f"## {label}", ""]
        for e in entries:
            out += [f"### {e.heading}", ""]
            if e.href:
                out += [f"Source: [{e.label}]({e.href})", ""]
            if e.para:
                out += [e.para, ""]
            if e.used_by is not None:
                out += [f"Used by: {e.used_by}", ""]
            for d in e.diagrams:
                if d.heading:
                    out += [f"#### {d.heading}", ""]
                if d.para:
                    out += [d.para, ""]
                out += [_mermaid_block(d.body)]
                if d.href:
                    out += [f"Source: [{d.label}]({d.href})", ""]
    return "\n".join(out).rstrip("\n") + "\n"


