SCRIPT = (
    'if (window.mermaid) { mermaid.initialize({ startOnLoad: true, securityLevel: "strict", '
    'theme: window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "default" }); }'
)


def to_html(layers: list[tuple[str, list[Entry]]]) -> str:
    esc = html.escape
    out = ["<!doctype html>", '<html lang="en">', "<head>", '<meta charset="utf-8">',
           '<meta name="viewport" content="width=device-width, initial-scale=1">',
           "<title>Architecture</title>", f"<style>\n{CSS}</style>", "</head>", "<body>", "<main>",
           "<h1>Architecture</h1>"]
    for label, entries in layers:
        out.append(f'<section class="layer">\n<h2>{esc(label)}</h2>')
        for e in entries:
            out.append(f"<h3>{esc(e.heading)}</h3>")
            if e.href:
                out.append(f'<p class="src"><a href="{esc(e.href)}">{esc(e.label or "")}</a></p>')
            if e.para:
                out.append(f"<p>{esc(e.para)}</p>")
            if e.used_by is not None:
                out.append(f"<p>Used by: {esc(e.used_by)}</p>")
            for d in e.diagrams:
                out.append('<div class="diagram">')
                if d.heading:
                    out.append(f"<h4>{esc(d.heading)}</h4>")
                if d.para:
                    out.append(f"<p>{esc(d.para)}</p>")
                out.append(f'<div class="frame"><pre class="mermaid">{esc(d.body)}</pre></div>')
                if d.href:
                    out.append(f'<p class="src"><a href="{esc(d.href)}">{esc(d.label or "")}</a></p>')
                out.append("</div>")
        out.append("</section>")
    out += ["</main>", f'<script src="{MERMAID_URL}" integrity="{MERMAID_SRI}" crossorigin="anonymous"></script>',
            f"<script>{SCRIPT}</script>", "</body>", "</html>"]
    return "\n".join(out) + "\n"


def render(project: Path) -> dict[str, str]:
    """{relpath: text} for both generated files. Raises InputError; writes nothing."""
    layers = build(Path(project))
    return {GENERATED_MD: to_markdown(layers), GENERATED_HTML: to_html(layers)}


# --- git -------------------------------------------------------------------------------------------


def _git(project: Path, *args: str) -> subprocess.CompletedProcess:
    try:
        return subprocess.run(["git", "-C", str(project), "-c", "core.quotePath=false", *args],
                              capture_output=True, text=True, encoding="utf-8", errors="replace")
    except OSError as exc:
        return subprocess.CompletedProcess(args, 127, "", str(exc))


def _safe_ref(ref: str, what: str) -> str:
    if ref.startswith("-"):
        raise InputError(f"{what} {ref!r} is not a ref")
    return ref


def resolve_base(project: Path, explicit: str | None) -> str | None:
    """The diff base commit. An explicit ref that does not resolve raises InputError; with none
    given, the merge-base with the upstream, else with origin/HEAD, else None."""
    if explicit:
        r = _git(project, "rev-parse", "--verify", "--quiet", _safe_ref(explicit, "--base") + "^{commit}")
        if r.returncode != 0:
            raise InputError(f"--base {explicit} does not resolve here; fetch it first "
                             "(fetch-depth: 0, or fetch the base SHA)")
        return r.stdout.strip()
    for other in ("@{upstream}", "origin/HEAD"):
        r = _git(project, "merge-base", "HEAD", other)
        if r.returncode == 0 and r.stdout.strip():
            return r.stdout.strip()
    return None


DIFF = ("diff", "-w", "-U0", "--no-color", "--no-ext-diff", "--no-renames", "--relative")


def parse_diff(text: str) -> dict[str, list[tuple[str, str]]]:
    """{path: [(sign, line)]} for the added and removed lines of a unified diff."""
    files: dict[str, list[tuple[str, str]]] = {}
    cur: list[tuple[str, str]] | None = None
    old = ""
    in_hunk = False
    for line in text.split("\n"):
        if line.startswith("diff --git "):
            cur, in_hunk = None, False
        elif not in_hunk and line.startswith("--- "):
            old = line[4:]
        elif not in_hunk and line.startswith("+++ "):
            new = line[4:]
            path = new[2:] if new.startswith("b/") else (old[2:] if old.startswith("a/") else None)
            cur = files.setdefault(path, []) if path else None
        elif line.startswith("@@"):
            in_hunk = True
        elif in_hunk and cur is not None and line[:1] in ("+", "-"):
            cur.append((line[0], line[1:]))
    return files


def _diff(project: Path, *spec: str) -> dict[str, list[tuple[str, str]]]:
    r = _git(project, *DIFF, *spec)
    if r.returncode != 0:
        raise InputError(f"git diff {' '.join(spec)} failed: {r.stderr.strip() or 'no output'}; "
                         "a shallow clone needs the base fetched")
    return parse_diff(r.stdout)


# --- update trigger --------------------------------------------------------------------------------

SURFACE = (
    (frozenset({".rs"}), re.compile(r"^\s*pub\s+(fn|struct|enum|trait|type|const|static|mod|use)\b")),
    (frozenset({".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".mts", ".cts"}), re.compile(r"^\s*export\b")),
    (frozenset({".py"}), re.compile(r"^(__all__\b|(async\s+)?def\s+[A-Za-z]|class\s+[A-Za-z])")),
    (frozenset({".go"}), re.compile(r"^(func\s+(\([^)]*\)\s*)?[A-Z]|(type|var|const)\s+[A-Z])")),
)
MANIFEST_FILES = frozenset({"Cargo.toml", "package.json", "pyproject.toml", "go.mod"})
# Manifest lines that cannot be an internal dependency, even when they mention a component's name.
MANIFEST_METADATA = re.compile(
    r"""^\s*"?(name|version|description|authors?|edition|license|readme|repository|homepage|keywords|"""
    r"""categories|main|module|types|scripts|go|requires-python)"?\s*[=:\s]""")
FRONTMATTER_LINE = re.compile(r"^(title|kind|project|updated|component|path|depends-on):")
TRAILER = re.compile(r"^Docs-Unchanged:[ \t]*(.+?)[ \t]*:[ \t]*(\S.*)$", re.M)  # one line: no \s across a newline
TEST_DIRS = frozenset({"tests", "benches", "examples"})


def _is_test_path(rel: str) -> bool:
    parts = rel.split("/")
    return bool(TEST_DIRS.intersection(parts[:-1])) or fnmatch.fnmatchcase(parts[-1], "*_test.*")


def _owner(rel: str, by_depth: list):
    for c in by_depth:  # longest path first, the root last
        if c.path == "." or rel == c.path or rel.startswith(c.path + "/"):
            return c
    return None


def _surface_files(diff: dict, comps: list) -> dict[str, set[str]]:
    """{component name: files whose added or removed lines touch the public surface}."""
    by_depth = sorted(comps, key=lambda c: -1 if c.path == "." else len(c.path), reverse=True)
    idents = {c.name: re.compile(r"(?<![a-z0-9-])" + re.escape(components._norm(c.name)) + r"(?![a-z0-9-])")
              for c in comps}
    hits: dict[str, set[str]] = {}
    for rel, changes in diff.items():
        owner = _owner(rel, by_depth)
        if owner is None or _is_test_path(rel):
            continue
        folder, _, fname = rel.rpartition("/")
        is_manifest = fname in MANIFEST_FILES and (folder or ".") == owner.path
        pattern = next((p for exts, p in SURFACE if os.path.splitext(rel)[1] in exts), None)
        for _, line in changes:
            if pattern is not None and pattern.match(line):
                hit = True
            elif is_manifest and not MANIFEST_METADATA.match(line):
                norm = components._norm(line)
                hit = any(rx.search(norm) for n, rx in idents.items() if n != owner.name)
            else:
                hit = False
            if hit:
                hits.setdefault(owner.name, set()).add(rel)
                break
    return hits


def _page_body_changed(diff: dict, page_rel: str) -> bool:
    return any(t.strip() and t.strip() != "---" and not FRONTMATTER_LINE.match(t)
               for _, t in diff.get(page_rel, []))


def _trailer_names(project: Path, spec: str) -> set[str]:
    r = _git(project, "log", "--format=%B", spec)
    return {m.group(1) for m in TRAILER.finditer(r.stdout)} if r.returncode == 0 else set()


def stale_components(diff: dict, comps: list, waived: Callable[[], set[str]]) -> dict[str, list[str]]:
    """{component name: files} for each surface change with no page body change and no trailer.
    `waived` runs only when there is a hit, so a clean diff costs no `git log`."""
    stale = {}
    for name, files in _surface_files(diff, comps).items():
        if not _page_body_changed(diff, f"docs/components/{components.page_name(name)}.md"):
            stale[name] = sorted(files)
    if stale:
        skip = waived()
        stale = {n: f for n, f in stale.items() if n not in skip}
    return stale


# --- pr summary ------------------------------------------------------------------------------------

GITHUB_REMOTE = re.compile(
    r"^(?:https?://(?:[^@/]+@)?github\.com/|ssh://git@github\.com/|git@github\.com:)"
    r"([^/\s]+)/([^/\s]+?)(?:\.git)?/?$")


def pr_summary(project: Path, explicit_base: str | None) -> str:
    head = _git(project, "rev-parse", "HEAD")
    if head.returncode != 0:
        raise InputError(f"{project}: not a git repository with a commit")
    sha = head.stdout.strip()
    base = explicit_base or resolve_base(project, None)
    m = GITHUB_REMOTE.match(_git(project, "remote", "get-url", "origin").stdout.strip())
    link = (f"Architecture: [{GENERATED_MD}](https://github.com/{m.group(1)}/{m.group(2)}/blob/{sha}/{GENERATED_MD})"
            if m else f"Architecture: {GENERATED_MD} @ {sha}")
    if not _git(project, "branch", "-r", "--contains", "HEAD").stdout.strip():
        print("warning: HEAD is unpushed; the architecture.md link resolves only after push", file=sys.stderr)
    chunks: list[str] = []
    if base is None:
        print("warning: no diff base; changed diagrams omitted (pass --base)", file=sys.stderr)
    else:
        r = _git(project, "diff", "--name-only", "-z", "--relative", f"{base}...HEAD", "--", "docs")
        if r.returncode != 0:
            raise InputError(f"git diff {base}...HEAD failed: {r.stderr.strip()}")
        changed = sorted(p for p in r.stdout.split("\0")
                         if p.startswith("docs/") and p.endswith(".md") and not p.startswith("docs/generated/")
                         and (project / p).is_file())
        for rel in changed:
            doc = _read_doc(project, rel)
            chunks += [f"#### {rel}: {d.heading or doc.title}\n\n{_mermaid_block(d.body)}" for d in doc.diagrams]

    def block(k: int) -> str:
        text = link + "\n\n" + "\n".join(chunks[:k])
        if k < len(chunks):
            text = text.rstrip("\n") + f"\n\n{len(chunks) - k} more diagrams in architecture.md\n"
        return text.rstrip("\n") + "\n"

    k = len(chunks)
    while k > 0 and len(block(k)) > PR_SUMMARY_LIMIT:
        k -= 1
    return block(k)


# --- command line ----------------------------------------------------------------------------------


def _trigger_mode(project: Path, arg: str | None) -> str:
    if arg is None:
        node = components.read_policy(project).get("docs", {})
        node = node.get("components", {}) if isinstance(node, dict) else {}
        arg = node.get("trigger", "warn") if isinstance(node, dict) else "warn"
    if arg not in TRIGGER_MODES:
        raise InputError(f"docs.components.trigger {arg!r}: expected one of {', '.join(TRIGGER_MODES)}")
    return arg


def run_trigger(project: Path, explicit_base: str | None, mode: str) -> int:
    """The update trigger over base...HEAD. Exit 0 clean or warn, 1 in fail mode."""
    base = explicit_base or resolve_base(project, None)
    if base is None:
        print(NO_BASE, file=sys.stderr)
        return 1 if mode == "fail" else 0
    comps = components.resolve(project)
    diff = _diff(project, f"{base}...HEAD")
    stale = stale_components(diff, comps, lambda: _trailer_names(project, f"{base}..HEAD"))
    level = "error" if mode == "fail" else "warning"
    for name in sorted(stale):
        print(f"{level}: component-page-stale: {name}: {', '.join(stale[name])}", file=sys.stderr)
    if stale:
        print("update the component page body, or add a 'Docs-Unchanged: <name>: <reason>' commit trailer",
              file=sys.stderr)
    return 1 if stale and mode == "fail" else 0


def run_audit(project: Path, rev_range: str) -> int:
    r = _git(project, "rev-list", "--first-parent", "--reverse", "--parents", _safe_ref(rev_range, "range"))
    if r.returncode != 0:
        raise InputError(f"range {rev_range} does not resolve: {r.stderr.strip()}")
    comps = components.resolve(project)
    commits = [ln.split() for ln in r.stdout.splitlines() if len(ln.split()) > 1]
    hits = 0
    for sha, parent, *_ in commits:
        stale = stale_components(_diff(project, parent, sha), comps,
                                 lambda: _trailer_names(project, f"{parent}..{sha}"))
        for name in sorted(stale):
            print(f"{sha}\t{name}\t{', '.join(stale[name])}")
            hits += 1
    print(f"{hits} hits over {len(commits)} commits", file=sys.stderr)
    return 0


def run_check(project: Path, args, base: str | None) -> int:
    code = 0
    for rel, text in sorted(render(project).items()):
        try:
            current = (project / rel).read_bytes()
        except OSError:
            current = None
        if current != text.encode("utf-8"):
            print(f"error: {rel} is out of date; run: {TOOL} {args.path}", file=sys.stderr)
            code = 1
    if not args.no_trigger and (project / "docs" / "components").is_dir():
        code = max(code, run_trigger(project, base, _trigger_mode(project, args.trigger)))
    return code


def run_write(project: Path) -> int:
    for rel, text in sorted(render(project).items()):
        target = project / rel
        data = text.encode("utf-8")
        if target.is_file() and target.read_bytes() == data:
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)
    return 0


def main(argv: list[str] | None = None, version=sys.version_info) -> int:
    found = tuple(version)[:3]
    if found[:2] < MIN_PYTHON:
        print(f"error: python {'.'.join(map(str, MIN_PYTHON))}+ required, found "
              f"{'.'.join(map(str, found))}", file=sys.stderr)
        return 2
    parser = argparse.ArgumentParser(description="Render a project's docs into docs/generated/.")
    parser.add_argument("path", nargs="?", default=".")
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true", help="exit 1 if the generated files drifted")
    mode.add_argument("--pr-summary", action="store_true", help="print a markdown block for the PR description")
    mode.add_argument("--trigger-audit", metavar="RANGE", help="list trigger hits over merged commits")
    parser.add_argument("--base", metavar="REF", help="diff base (CI passes the PR base SHA)")
    parser.add_argument("--trigger", choices=TRIGGER_MODES,
                        help="update-trigger mode (default: policy docs.components.trigger, else warn)")
    parser.add_argument("--no-trigger", action="store_true", help="with --check, skip the update trigger")
    args = parser.parse_args(argv)
    project = Path(args.path)
    try:
        if not project.is_dir():
            raise InputError(f"{project}: not a directory")
        base = resolve_base(project, args.base) if args.base else None  # unresolvable: exit 2 in any mode
        if args.check:
            return run_check(project, args, base)
        if args.pr_summary:
            sys.stdout.write(pr_summary(project, base))
            return 0
        if args.trigger_audit:
            return run_audit(project, args.trigger_audit)
        return run_write(project)
    except components.NeedsInput as exc:
        print(json.dumps(components.needs_input_result(exc), indent=2))
        return 3
    except (InputError, components.ManifestError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
